/* ---------- data ---------- */
function profile(){return read('bw_profile_v1_full',{})}
function saveProfile(patch){var p=Object.assign(profile(),patch,{updatedAt:new Date().toISOString()});write('bw_profile_v1_full',p);var b=read('bw_profile',{skin:'',concerns:[]});b.skin=p.skinBase==='مطمئن نیستم'?'نامطمئن':(p.skinBase||'');write('bw_profile',b);if(typeof window.renderAdvice==='function')try{window.renderAdvice()}catch(e){}}
function routineIds(){var ids=read('bw_check_products',[]);return Array.isArray(ids)?ids.filter(function(id){return P(id)}):[]}
function times(){var t=read('bw_check_times',{});return t&&typeof t==='object'?t:{}}
