/* ---------- where to buy: live store search in a new tab (prices, discount, installments) ---------- */
function shopQuery(p){return String(p.name||'').replace(/[،,]?\s*[۰-۹0-9]+\s*(میلی‌لیتر|میل|ml|گرم)\b.*$/i,'').trim()}
function go(url){var u;try{u=new URL(url)}catch(e){return ''}if(!LIVE)return u.href;var d='';try{d=localStorage.getItem('bw_device')||''}catch(e){}return '/go?s='+(/khanoumi\.com$/i.test(u.hostname)?'kh':'dk')+'&u='+encodeURIComponent(u.href)+(d?'&d='+encodeURIComponent(d):'')}
function affOn(){return !!(CFG&&CFG.aff&&(CFG.aff.dk||CFG.aff.kh))}
function supportBuyHtml(name){return '<div class="sw-shops"><button type="button" class="sw-shop sw-support-buy" data-sbuy="'+esc(name)+'"><b>🛍 خریدش با ما</b><small>همکارامون برای قیمت و ارسال باهات هماهنگ می‌کنن</small></button></div>'}
function shopHtml(p){if(LIVE&&!affOn())return supportBuyHtml(p.name);var q=encodeURIComponent(shopQuery(p));return '<div class="sw-shops"><a class="sw-shop" target="_blank" rel="noopener sponsored" href="'+go('https://www.digikala.com/search/?q='+q)+'"><b>دیجی‌کالا</b><small>خرید قسطی و اعتباری</small></a><a class="sw-shop" target="_blank" rel="noopener sponsored" href="'+go('https://www.khanoumi.com/search?q='+q)+'"><b>خانومی</b><small>فروشگاه تخصصی آرایشی</small></a></div><p class="sw-sub" style="margin-top:8px">لینک همکاری؛ روی «بخر/نخر» هیچ اثری نداره 💜 قیمت و قسط رو همون‌جا ببین و قبل خرید اصالت و تاریخ انقضا رو چک کن</p>'}
