var askInput=$('#swAsk',home),suggestBox=$('#swSuggest',home),resultBox=$('#swResult',home);
function matchAll(q){q=norm(q);if(q.length<2)return [];var w=q.split(' ').filter(function(t){return t.length>=2});var out=[];
 LIST.forEach(function(p){var n=norm(p.name),h=norm(p.name+' '+(p.en||'')+' '+(p.cat||'')+' '+(p.brand||''));var sc=n.indexOf(q)===0?4:n.indexOf(q)>=0?3:h.indexOf(q)>=0?2:(w.length>1&&w.every(function(t){return h.indexOf(t)>=0}))?1:0;if(sc)out.push([sc,p])});
 return out.sort(function(a,b){return b[0]-a[0]}).map(function(x){return x[1]})}
function matches(q){return matchAll(q).slice(0,6)}
var BEST=[];if(LIVE)fetch('/bestsellers.json').then(function(r){return r.json()}).then(function(d){BEST=(d&&d.items||[]).filter(function(x){return x&&(x.name_fa||x.name_en)});renderBest()}).catch(function(){});
