var PENDING=null;
function runQ(q){askInput.value=q;var m=matches(q);if(m[0]&&(m.length===1||norm(m[0].name)===norm(q)))checkProduct(m[0].id);else askOutside(q)}
/* ---------- current routine everywhere: result + run-out date in one tap, schematic in the skin profile ---------- */
function metaHtml(id){var m=refillMeta()[id]||{},d=daysLeft(id),w=m.worked||'';
 var when=(!m.since||m.auto)?'<span class="sw-rmq">کی شروعش کردی؟</span><button type="button" data-rsince="'+id+'|0">این هفته</button><button type="button" data-rsince="'+id+'|30">یه ماه پیش</button><button type="button" data-rsince="'+id+'|60">بیشتر</button>'
  :'<span class="sw-rmq">⏳ '+(d>0?'حدوداً '+fa(d)+' روز دیگه تموم می‌شه':'احتمالاً تموم شده')+'</span><button type="button" data-rsince="'+id+'|new">نو خریدم</button>';
 var res='<span class="sw-rmq">جواب داده؟</span>'+[['yes','👍','آره'],['meh','🤔','هنوز معلوم نیست'],['no','👎','نه']].map(function(x){return '<button type="button" data-rw="'+id+'|'+x[0]+'" aria-pressed="'+(w===x[0])+'" aria-label="'+x[2]+'">'+x[1]+'</button>'}).join('');
 return '<div class="sw-rmeta" data-meta="'+id+'"><div>'+res+'</div><div>'+when+'</div></div>'}
document.addEventListener('click',function(e){var b=e.target.closest('[data-rw],[data-rsince]');if(!b)return;e.stopPropagation();
 var v=(b.dataset.rw||b.dataset.rsince).split('|'),id=v[0];
 if(b.dataset.rw){var cur=(refillMeta()[id]||{}).worked;setRefill(id,{worked:cur===v[1]?'':v[1]});if(window.bwTrack&&cur!==v[1])window.bwTrack(v[1]==='yes'?'refill_worked':v[1]==='no'?'refill_not_worked':'result_unsure');if(cur!==v[1])toast(v[1]==='yes'?'عالیه 💜 قبل از تموم شدن یادت می‌ندازم':v[1]==='no'?'ثبت شد؛ دفعه‌ی بعد جایگزین بهتر برات پیدا می‌کنم':'باشه، چند هفته دیگه دوباره می‌پرسم')}
 else{var since=v[1]==='new'?0:Number(v[1]);setRefill(id,{since:new Date(Date.now()-since*864e5).toISOString(),auto:false,snooze:null})}
 $$('[data-meta="'+id+'"]').forEach(function(x){x.outerHTML=metaHtml(id)});try{renderRefill()}catch(er){}try{renderProfRoutine()}catch(er){}},true);
function profRoutineHtml(){var ids=routineIds(),m=refillMeta();
 var lane=function(slot){var list=ids.filter(function(id){return timeOf(id)===slot}).sort(function(a,b){return (ORDER[F(a)&&F(a).role]||5)-(ORDER[F(b)&&F(b).role]||5)});
  return '<div class="sw-plane"><b>'+(slot==='am'?'☀ صبح':'☾ شب')+'</b>'+(list.length?'<div class="sw-pline">'+list.map(function(id){var d=daysLeft(id),w=(m[id]||{}).worked,auto=!(m[id]||{}).since||(m[id]||{}).auto;
   return '<button type="button" class="sw-pstep" data-pedit="1">'+thumb(P(id))+'<span class="nm">'+esc(P(id).name)+'</span><small>'+(w==='yes'?'👍 ':w==='no'?'👎 ':w==='meh'?'🤔 ':'')+(auto||d===null?'':d>0?'⏳ '+fa(d)+' روز':'⏳ تموم شد')+'</small></button>'}).join('<i class="sw-parrow">←</i>')+'</div>':'<small class="sw-sub">هنوز چیزی ثبت نکردی</small>')+'</div>'};
 return '<div class="sw-prt-h"><b>🧴 روتین فعلی من</b><small class="sw-sub">هر محصولی رو با همین روتین می‌سنجم</small></div>'+lane('am')+lane('pm')+'<button type="button" class="sw-btn" data-pedit="1">'+(ids.length?'ویرایش، ثبت نتیجه و زمان تموم شدن':'+ ثبت روتین فعلیم')+'</button>'}
function renderProfRoutine(){var host=document.querySelector('#profile .section');if(!host)return;var c=document.getElementById('swProfRtn');
 if(!c){c=document.createElement('div');c.id='swProfRtn';c.className='sw-card sw-prt';var reg=host.querySelector('.profile-register-card');if(reg)reg.after(c);else host.prepend(c);c.addEventListener('click',function(e){if(e.target.closest('[data-pedit]'))routineSheet()})}
 c.innerHTML=profRoutineHtml()}
