document.addEventListener('change',function(e){if(e.target.closest&&e.target.closest('#routine-list')&&e.target.dataset.field==='name')setTimeout(function(){try{syncFromProfile();renderRtn();renderProfRoutine()}catch(er){}},120)});
// home search: «I already use this» is always free — never a diamond
askInput.addEventListener('input',function(){var q=askInput.value.trim();if(q.length<3)return;suggestBox.insertAdjacentHTML('beforeend','<button type="button" class="sw-sitem sw-own" data-rtnadd="1"><span class="sw-thumb"><b>+</b></span><span>الان اینو می‌زنم؛ به روتین فعلیم اضافه‌ش کن<small>الماس کم نمی‌شه</small></span></button>')});
suggestBox.addEventListener('click',function(e){if(!e.target.closest('[data-rtnadd]'))return;var q=askInput.value.trim();if(needProfile())return;var m=matches(q),known=findProduct(q)||(m.length===1?m[0]:null);suggestBox.innerHTML='';
 if(known){addToRoutine(known.id);askInput.value='';addedSnack(known.name);return}
 if(guessRole(q)){addOwn(q,'','',true);askInput.value='';addedSnack(q);return}
 routineSheet();var inp=$('#swRq');if(inp){inp.value=q;inp.dispatchEvent(new Event('input'));var own=$('#swRqList [data-ownadd]');if(own)own.click()}askInput.value=''});
// the long profile form was filled at page load; bring it up to date (3-card onboarding, routine) so saving it never overwrites newer answers
function refreshProfileForm(){var f=document.getElementById('profile-form');if(!f)return;var p=profile();
 Array.prototype.forEach.call(f.elements,function(el){if(!el.name||!(el.name in p))return;var v=p[el.name];if(el.type==='checkbox')el.checked=Array.isArray(v)?v.indexOf(el.value)>=0:v===true;else if(el.type!=='radio'&&typeof v!=='object')el.value=v});
 if(window.bwProfileRoutineRows)window.bwProfileRoutineRows()}

