function raddBtn(id,mini){var inR=routineIds().indexOf(id)>=0;return '<button type="button" class="'+(mini?'sw-vadd':'sw-radd')+'" data-radd="'+esc(id)+'"'+(inR?' disabled':'')+' aria-label="اضافه به روتین فعلیم">'+(inR?'✓':mini?'＋':'＋ روتینم')+'</button>'}
