function start(){window.switchTab('sw-home');var qp='';try{var sp=new URLSearchParams(location.search);qp=(sp.get('q')||'').trim().slice(0,120);
  // shared from a shop or Instagram (Android "Share → BeautyWallet"): the link if there is one, else the product name
  if(!qp&&(sp.get('su')||sp.get('sx')||sp.get('st'))){var tx=(sp.get('sx')||'')+' '+(sp.get('st')||''),lk=sp.get('su')||((tx.match(/https?:\/\/\S+/)||[])[0])||'';qp=(lk||tx.replace(/https?:\/\/\S+/g,'')).replace(/\s+/g,' ').trim().slice(0,300);if(qp&&window.bwTrack)window.bwTrack('share_in')}}catch(e){}
 if(qp){try{history.replaceState(null,'',location.pathname)}catch(e){}askInput.value=qp;if(!profile().skinBase){PENDING=qp;write('bw_sw_seen',true);setTimeout(function(){openOnboarding();toast('اول سه تا سؤال کوچولو، بعد «'+qp.slice(0,24)+'» رو می‌سنجم 💜')},500)}else setTimeout(function(){runQ(qp)},300);return}
if(!/[?&]gift=/.test(location.search)&&!profile().skinBase&&!read('bw_sw_seen',false)){write('bw_sw_seen',true);setTimeout(openOnboarding,700)}}
if(document.readyState==='complete')setTimeout(start,50);else window.addEventListener('load',function(){setTimeout(start,50)});
/* ---------- full catalog: everything we know (built-in + researched by shoppers), searchable, light photos ---------- */
function catChip(){return '<button type="button" class="sw-sitem sw-allres" data-allcat=""><span>📚 کل کاتالوگ بیوتی‌ولت رو ببین<small>'+fa(LIST.length)+' محصول با عکس و ترکیبات</small></span></button>'}
var CAT_ORDER=['شوینده','میسلار واتر','تونر','سرم','مرطوب‌کننده','آبرسان','ضد آفتاب','ضدآفتاب','ضد جوش','ضد لک','دور چشم','ماسک'];
function catalogSheet(q0){var cats={};LIST.forEach(function(p){var c=p.cat||'سایر';cats[c]=(cats[c]||0)+1});
 var names=Object.keys(cats).sort(function(a,b){var ia=CAT_ORDER.indexOf(a),ib=CAT_ORDER.indexOf(b);return (ia<0?99:ia)-(ib<0?99:ib)||cats[b]-cats[a]});var cat='',q=q0||'',shown=40;
 openSheet('<div class="sw-cat"><b class="sw-cat-h">کاتالوگ بیوتی‌ولت <small>'+fa(LIST.length)+' محصول</small></b><input id="swCatQ" class="sw-cat-q" type="search" placeholder="اسم، برند یا نوع محصول…" aria-label="جست‌وجو در کاتالوگ" value="'+esc(q)+'"><div class="sw-chips sw-cat-chips"><button type="button" class="sw-chip" data-cc="" aria-pressed="true">همه</button>'+names.map(function(c){return '<button type="button" class="sw-chip" data-cc="'+esc(c)+'" aria-pressed="false">'+esc(c)+' <small>'+fa(cats[c])+'</small></button>'}).join('')+'</div><div id="swCatList" class="sw-cat-list"></div></div>');
 var sh=$('#swSheet'),inp=$('#swCatQ',sh),box=$('#swCatList',sh);
 function list(){var src=q.trim().length>=2?matchAll(q):LIST.slice().sort(function(a,b){return (b.image?1:0)-(a.image?1:0)});if(cat)src=src.filter(function(p){return (p.cat||'سایر')===cat});return src}
 function draw(){var l=list();box.innerHTML=(l.length?l.slice(0,shown).map(function(p){return '<div class="sw-srow"><button type="button" class="sw-sitem" data-cpick="'+esc(p.id)+'">'+thumb(p)+'<span>'+esc(p.name)+'<small>'+esc((window.BWCatalog.caption(p.id)||p.cat||'')+(p.bank?' · بررسی‌شده':''))+'</small></span></button>'+raddBtn(p.id)+'</div>'}).join('')+(l.length>shown?'<button type="button" class="sw-ghost sw-cat-more" data-cmore="1">'+fa(l.length-shown)+' محصول دیگه ←</button>':''):'<p class="sw-sub">تو کاتالوگ پیدا نشد؛ از صفحه‌ی اول اسمش رو بنویس تا خودم ترکیباتش رو پیدا کنم.</p>')}
 draw();inp.addEventListener('input',function(){q=inp.value;shown=40;draw()});
 sh.onclick=function(e){var c=e.target.closest('[data-cc]');if(c){cat=c.dataset.cc;$$('[data-cc]',sh).forEach(function(b){b.setAttribute('aria-pressed',String(b===c))});shown=40;draw();return}
  if(e.target.closest('[data-cmore]')){shown+=40;draw();return}var p=e.target.closest('[data-cpick]');if(p){closeSheet();checkProduct(p.dataset.cpick);var r=$('.sw-result',resultBox);if(r)r.scrollIntoView({behavior:'smooth',block:'start'})}}}

